(()=>{'use strict';
const en=document.documentElement.lang==='en',L=(vi,eng)=>en?eng:vi,loc=en?'en-US':'vi-VN',fmt=n=>n==null?L('Chưa xác minh','Not verified'):new Intl.NumberFormat(loc).format(n),txt=v=>v==null?L('Chưa xác minh','Not verified'):typeof v==='object'?(v[en?'en':'vi']||'—'):v;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const names={apartment:L('Căn hộ','Apartment'),shophouse:'Shophouse',podium:L('Shop khối đế','Podium shop'),lowrise:L('Shophouse thấp tầng','Low-rise shophouse'),developer:L('Chủ đầu tư','Developer'),owner:L('Chủ nhà hiện tại','Current homeowner'),sold:L('Đã bán sơ cấp','Primary sale completed'),unsold:L('Chưa bán sơ cấp','Primary sale not completed'),available:L('Available · đang chào bán','Available · offered for sale'),unavailable:L('Unavailable · không chào bán','Unavailable · not offered for sale'),rented:L('Đang cho thuê','Leased'),vacant:L('Chưa cho thuê được','Vacant'),received:L('Đã thu tiền kỳ này','Rent received this period'),unpaid:L('Chưa thu tiền kỳ này','Rent not received this period'),none:L('Không phát sinh tiền thuê','No rent for this period'),pending:L('Chờ xác minh','Verification pending'),clear_demo:L('Hồ sơ đạt trong mô phỏng','Checks passed in simulation'),encumbered:L('Nghĩa vụ bảo đảm chưa xử lý','Unresolved encumbrance')};
const root=document.getElementById('grandpark-root');
function candidate(u){return u.listing_status==='available'&&['developer','owner'].includes(u.current_owner_type)&&u.physical_status==='existing_demo'}
function eligible(u){return candidate(u)&&u.verification_status==='clear_demo'&&u.tokenization_status==='not_issued'}
function stage(u){return !candidate(u)?L('Không mở tiếp nhận','Not accepting'):eligible(u)?L('Đủ bước mở mô phỏng','Ready for demo onboarding'):u.verification_status==='encumbered'?L('Tạm chặn · cần xử lý nghĩa vụ','Blocked · resolve encumbrance'):L('Ứng viên · chờ thẩm định','Candidate · review required')}
function opts(items,all){return '<option value="all">'+all+'</option>'+items.map(([k,v])=>'<option value="'+esc(k)+'">'+esc(v)+'</option>').join('')}
fetch('grandpark-data.json').then(r=>{if(!r.ok)throw Error('data');return r.json()}).then(d=>{
 const source=id=>d.sources.find(s=>s.id===id),links=ids=>ids.map(id=>{const s=source(id);return '<a href="'+esc(s.url)+'" target="_blank" rel="noopener noreferrer">'+esc(s.title)+' ↗</a>'}).join('<br>');
 root.innerHTML=`<section id="grandpark"><div class="eyebrow">${L('Case nghiên cứu độc lập · dữ liệu công khai','Independent case study · public reference data')}</div><h2>Vinhomes Grand Park</h2><p class="muted">${L('TP. Hồ Chí Minh · khu vực Quận 9 cũ. Chỉ nghiên cứu căn hộ và shophouse hiện hữu; không coi cả đại đô thị đã hoàn thành.','Ho Chi Minh City · former District 9 area. Focused on existing apartments and shophouses; the entire township is not assumed complete.')}</p><div class="notice">${L('Không liên kết, được tài trợ hoặc xác nhận bởi Vingroup, Vinhomes hay Masterise Homes. Thông tin phân khu có nguồn; tất cả hồ sơ căn, người bán và trạng thái bên dưới là giả lập, không phải bảng hàng thực.','Not affiliated with, sponsored by or endorsed by Vingroup, Vinhomes or Masterise Homes. Subdivision references are sourced; all individual units, sellers and statuses below are fictional, not live inventory.')}</div><div class="gp-stats"><div><strong>271 ha</strong><span>${L('Quy mô công bố','Published project area')}</span></div><div><strong>~23%</strong><span>${L('Mật độ xây dựng công bố','Published construction density')}</span></div><div><strong>36 ha</strong><span>${L('Đại công viên','Grand park')}</span></div><div><strong>71</strong><span>${L('Tòa căn hộ theo trang dự án','Apartment towers per project page')}</span></div></div><p class="muted">${L('Kiểm tra nguồn: 08/11/2026. Ảnh chụp nghiên cứu cập nhật thủ công; chưa có đồng bộ hằng ngày, giá giao dịch hay tồn kho thời gian thực.','Sources checked: 8 Nov 2026. Manually researched snapshot; no daily synchronization, transaction-price feed or real-time inventory.')}</p><details><summary>${L('Nguồn quy mô & phạm vi dữ liệu','Project sources & data coverage')}</summary><p>${links(['gp','market'])}</p><p class="muted">${L('76 ha cây xanh và mặt nước là một chỉ tiêu cảnh quan công bố, không cộng vào diện tích đất. Diện tích phân khu có thể khác ranh giới hoặc thời điểm; không cộng các hàng bên dưới để suy ra tổng. Chưa có danh sách pháp lý tất cả căn, tầng, lô hoặc bản quy hoạch 1/500 đã đối soát.','76 ha of greenery and water is a published landscape metric, not extra land. Subdivision boundaries or reporting dates may differ; do not sum rows into a project total. A reconciled legal unit/floor/lot registry and approved 1:500 plan are not available here.')}</p></details><h3>${L('Cấu trúc phân khu','Subdivision directory')}</h3><p class="muted">${L('Các khu được ghi riêng; không mặc định cùng một pháp nhân sở hữu hoặc cùng đơn vị phát hành. Bấm tên khu để xem nguồn, mâu thuẫn và chi tiết.','Each subdivision is recorded separately; a shared owner or issuer is not assumed. Expand a subdivision for sources, conflicts and details.')}</p><div id="gp-zones"></div><div class="gp-subtypes"><h3>${L('Hai nhóm shophouse cần phân biệt','Two shophouse subtypes')}</h3>${d.shophouse_subtypes.map(s=>'<p><b>'+esc(txt(s.name))+'</b> · '+esc(txt(s.ranges))+'</p>').join('')}<p class="muted">${L('Dải diện tích là tham khảo công bố, chưa đồng nhất tim tường/thông thủy/đất/tổng sàn. Không dùng thay giấy tờ từng căn. Nguồn shophouse 2021 là dữ liệu lịch sử, không phải lượng còn bán.','Published area ranges may use different gross/net/land/total-floor bases. They do not replace unit documents. The 2021 shophouse source is historical, not remaining stock.')}</p><details><summary>${L('Nguồn loại hình shophouse','Shophouse sources')}</summary><p>${links(['shops','manhattan','cbre'])}</p></details></div></section>
 <section id="assets"><div class="eyebrow">${L('Bộ trạng thái độc lập','Independent state dimensions')}</div><h2>${L('Một căn, nhiều thuộc tính cùng lúc.','One property, multiple states.')}</h2><p>${L('Căn hộ hoặc shophouse có thể đang cho thuê và đồng thời chào bán. Căn chủ đầu tư chưa bán vẫn có thể đang khai thác. Available chỉ nói về nhu cầu bán, không nói về tình trạng thuê.','An apartment or shophouse may be leased and offered for sale at the same time. An unsold developer-held unit may still generate rent. Available describes sale availability, not occupancy.')}</p><div class="gp-model"><span>${L('Loại tài sản','Asset type')}</span><span>${L('Chủ sở hữu hiện tại','Current owner')}</span><span>${L('Lịch sử bán sơ cấp','Primary-sale history')}</span><span>Available / Unavailable</span><span>${L('Thuê & thực thu','Lease & receipts')}</span><span>${L('Thẩm định & token hóa','Review & tokenization')}</span></div><p class="muted">${L('Cấu trúc định danh: Dự án → phân khu → cụm (nếu có) → tòa/lô → tầng → căn. Với shop thấp tầng dùng lô/đường và số tầng xây dựng. Mỗi loại diện tích có trường riêng.','Identity hierarchy: project → subdivision → cluster (if applicable) → building/lot → floor → unit. Low-rise shops use lot/street and storey count. Different area bases have separate fields.')}</p><div class="notice">${L('8 hồ sơ tình huống giả lập. Không căn nào là lời chào đầu tư hoặc được xác nhận đang bán. “Đủ bước mở mô phỏng” chỉ có nghĩa bộ kiểm tra giả lập đạt, không phải phê duyệt pháp lý.','8 fictional scenario records. None is an investment offer or a confirmed listing. “Ready for demo onboarding” means simulated checks pass, not legal approval.')}</div><div class="gp-filters"><label>${L('Loại tài sản','Asset type')}<select id="gp-type">${opts([['apartment',names.apartment],['shophouse',names.shophouse]],L('Tất cả loại','All types'))}</select></label><label>${L('Phân khu','Subdivision')}<select id="gp-zone">${opts(d.zones.map(z=>[z.id,z.name]),L('Tất cả khu','All subdivisions'))}</select></label><label>${L('Bên sở hữu','Owner type')}<select id="gp-owner">${opts([['developer',names.developer],['owner',names.owner]],L('Tất cả chủ sở hữu','All owners'))}</select></label><label>${L('Chào bán','Sale availability')}<select id="gp-listing">${opts([['available',names.available],['unavailable',names.unavailable]],L('Mọi trạng thái bán','Any sale status'))}</select></label><label>${L('Cho thuê','Lease status')}<select id="gp-lease">${opts([['rented',names.rented],['vacant',names.vacant]],L('Mọi trạng thái thuê','Any lease status'))}</select></label><label>${L('Thực thu kỳ này','Rent receipts')}<select id="gp-receipt">${opts([['received',names.received],['unpaid',names.unpaid],['none',names.none]],L('Mọi trạng thái thu','Any receipt status'))}</select></label></div><p id="gp-count" class="muted" aria-live="polite"></p><div id="gp-units" class="properties"></div><button id="gp-reset" class="cta outline">${L('Xóa bộ lọc','Reset filters')}</button></section>
 <section id="gp-onboarding"><div class="eyebrow">${L('Mô phỏng tiếp nhận tài sản','Asset onboarding simulation')}</div><h2>${L('Đang bán là bước đầu, chưa phải đã phát hành.','For sale is a starting point, not issuance.')}</h2><div class="gp-lab"><div><label>${L('Loại tài sản','Asset type')}<select id="lab-type"><option value="apartment">${names.apartment}</option><option value="shophouse">Shophouse</option></select></label><label>${L('Chủ sở hữu','Owner')}<select id="lab-owner"><option value="owner">${names.owner}</option><option value="developer">${names.developer}</option></select></label><label>${L('Nhu cầu bán','Sale availability')}<select id="lab-listing"><option value="available">Available</option><option value="unavailable">Unavailable</option></select></label><label>${L('Cho thuê','Lease status')}<select id="lab-lease"><option value="rented">${names.rented}</option><option value="vacant">${names.vacant}</option></select></label><div class="gp-checks"><label><input type="checkbox" id="lab-existing" checked> ${L('Đã hiện hữu, xác minh bàn giao (giả lập)','Existing and handover verified (simulated)')}</label><label><input type="checkbox" id="lab-consent"> ${L('Chủ sở hữu đồng ý và có thẩm quyền bán (giả lập)','Owner consent and sale authority (simulated)')}</label><label><input type="checkbox" id="lab-title"> ${L('Hồ sơ quyền và nghĩa vụ đã kiểm tra (giả lập)','Title and encumbrances reviewed (simulated)')}</label><label><input type="checkbox" id="lab-structure"> ${L('Cấu trúc pháp lý và định giá được duyệt (giả lập)','Legal structure and valuation approved (simulated)')}</label></div></div><div class="result"><small>${L('KẾT QUẢ KIỂM TRA GIẢ LẬP','SIMULATED CHECK RESULT')}</small><h3 id="lab-result" aria-live="polite"></h3><p id="lab-reasons"></p><p id="lab-description"></p><hr><small>${L('Không mint token, không kết nối ví, không huy động tiền. Việc cho thuê không tự quyết định khả năng token hóa; quyền hợp đồng thuê phải được bảo toàn khi chuyển chủ.','No minting, wallet connection or fundraising. Lease status does not itself determine onboarding eligibility; tenant contract rights must be preserved on a change of ownership.')}</small></div></div><p class="muted">${L('Chủ nhà bán phần sở hữu sẵn có: tiền mua trả cho chủ nhà theo cấu trúc giao dịch; không mặc định là vốn mới vào chủ đầu tư. Quỹ tiền thuê được theo dõi tách biệt.','For a homeowner selling existing rights, purchase proceeds go to that seller under the transaction structure; they are not automatically new developer capital. Rental reserves remain separate.')}</p></section>
 <section id="gp-sources"><div class="eyebrow">${L('Nguồn & khả năng kiểm chứng','Sources & verifiability')}</div><h2>${L('Dữ liệu có ranh giới rõ.','Know what the data can prove.')}</h2><p>${L('Thông tin công khai dùng để dựng cấu trúc, không dùng suy đoán ai sở hữu căn nào. Giá rao bán, giá chốt giao dịch, giá trị thẩm định và doanh thu thuê là các trường riêng, hiện chưa được nhập cho căn thật.','Public references define the structure; they do not identify individual owners. Asking prices, completed transaction prices, appraised values and rental receipts are separate fields, currently unavailable for actual units.')}</p><details><summary>${L('Xem toàn bộ nguồn nghiên cứu','View all research sources')}</summary><ol>${d.sources.map(s=>'<li><a href="'+esc(s.url)+'" target="_blank" rel="noopener noreferrer">'+esc(s.title)+'</a> <small>· '+esc(s.kind)+' · 08/11/2026</small></li>').join('')}</ol><p class="muted">${L('official_search_extract: chỉ đọc được trích xuất tìm kiếm của tên miền chính thức; trang đầy đủ không truy xuất được. broker_reference: số liệu tham khảo từ đơn vị môi giới. Mọi nguồn có thể thay đổi sau ngày kiểm tra.','official_search_extract: only the official-domain search extract was available; the full page could not be retrieved. broker_reference: figures from a property broker. Sources may change after the check date.')}</p></details><p><a href="grandpark-data.json" download="Fual_GrandPark_Research_20261108.json">${L('Tải bộ dữ liệu có nguồn (JSON)','Download sourced dataset (JSON)')} ↗</a></p></section>`;
 document.getElementById('gp-zones').innerHTML=d.zones.map(z=>`<details class="gp-zone"><summary><span>${esc(z.name)}</span><span class="muted">${z.land_area_ha==null?'—':fmt(z.land_area_ha)+' ha'} · ${z.towers==null?'—':fmt(z.towers)+' '+L('tòa','towers')} ${z.needs_reconciliation?' · '+L('Cần đối chiếu','Needs reconciliation'):''}</span></summary><div class="gp-zone-info"><p><b>${L('Diện tích đất công bố','Published land area')}:</b> ${z.land_area_ha==null?L('Chưa chốt','Not established'):fmt(z.land_area_ha)+' ha'}</p><p><b>${L('Số sản phẩm công bố','Published product count')}:</b> ${esc(txt(z.published_units))}</p><p><b>${L('Loại / diện tích căn','Unit types / areas')}:</b> ${esc(txt(z.unit_area))}</p>${z.groups.length?'<p><b>'+L('Cụm / mã tòa công bố','Published clusters / building codes')+':</b> '+esc(z.groups.join(', '))+'</p>':''}<p class="muted">${esc(txt(z.note))}</p>${z.id==='origami'?'<p><b>'+L('Danh mục 21 tòa theo layout','21 published buildings by layout')+':</b></p>'+Object.entries(d.origami_towers).map(([k,v])=>'<p>'+esc(k)+': '+esc(v.join(', '))+'</p>').join(''):''}<p class="gp-source-links">${links(z.source_ids)}</p></div></details>`).join('');
 const fields=[['type','asset_type'],['zone','zone_id'],['owner','current_owner_type'],['listing','listing_status'],['lease','lease_status'],['receipt','rent_receipt_status']];
 function inventory(){const a=d.demo_units.filter(u=>fields.every(([id,key])=>{const v=document.getElementById('gp-'+id).value;return v==='all'||u[key]===v}));document.getElementById('gp-count').textContent=L('Hiển thị ','Showing ')+a.length+'/'+d.demo_units.length+L(' tình huống mô phỏng.',' simulated scenarios.');document.getElementById('gp-units').innerHTML=a.length?a.map(u=>`<article class="property"><div class="property-top"><span class="number">${esc(u.id)}</span><span class="tag ${eligible(u)?'':'empty'}">${stage(u)}</span></div><h3>${names[u.asset_type]} ${u.shophouse_subtype?'· '+names[u.shophouse_subtype]:''}</h3><p class="muted">${esc(d.zones.find(z=>z.id===u.zone_id).name)} · ${L('Không có mã căn thực','No actual unit number')}</p><dl class="gp-dl"><dt>${L('Chủ sở hữu','Owner')}</dt><dd>${names[u.current_owner_type]}</dd><dt>${L('Bán sơ cấp','Primary sale')}</dt><dd>${names[u.primary_sale_status]}</dd><dt>${L('Chào bán','Sale availability')}</dt><dd>${names[u.listing_status]}</dd><dt>${L('Cho thuê','Lease')}</dt><dd>${names[u.lease_status]}</dd><dt>${L('Thực thu','Rent receipts')}</dt><dd>${names[u.rent_receipt_status]}</dd><dt>${L('Hồ sơ','Review')}</dt><dd>${names[u.verification_status]}</dd></dl><p class="muted">${L('Chưa phát hành token. Diện tích, giá và chứng từ thật: chưa có.','No tokens issued. Actual area, price and supporting records: unavailable.')}</p></article>`).join(''):'<p>'+L('Không có tình huống phù hợp. Hãy xóa bộ lọc.','No matching scenarios. Reset the filters.')+'</p>'}
 fields.forEach(([id])=>document.getElementById('gp-'+id).addEventListener('change',inventory));document.getElementById('gp-reset').addEventListener('click',()=>{fields.forEach(([id])=>document.getElementById('gp-'+id).value='all');inventory()});inventory();
 function lab(){const val=id=>document.getElementById('lab-'+id),checks=['existing','consent','title','structure'];let reasons=[];if(val('listing').value!=='available')reasons.push(L('Chủ sở hữu không chào bán.','Owner is not offering the property.'));const rs={existing:L('Cần xác minh tài sản hiện hữu và bàn giao.','Verify existence and handover.'),consent:L('Cần sự đồng ý và thẩm quyền của người bán.','Obtain owner consent and sale authority.'),title:L('Cần kiểm tra quyền sở hữu và nghĩa vụ bảo đảm.','Review title and encumbrances.'),structure:L('Cần phê duyệt cấu trúc pháp lý và định giá.','Approve the legal structure and valuation.')};checks.forEach(k=>{if(!val(k).checked)reasons.push(rs[k])});document.getElementById('lab-result').textContent=reasons.length?(val('listing').value==='available'&&val('existing').checked?L('Ứng viên · còn bước kiểm tra','Candidate · checks outstanding'):L('Chưa mở tiếp nhận','Not accepting')):L('Đủ bước tiếp nhận trong mô phỏng','Ready for simulated onboarding');document.getElementById('lab-reasons').textContent=reasons.length?reasons.join(' '):L('Tất cả ô kiểm giả lập đã đạt. Không có phê duyệt thật hoặc giao dịch onchain.','All simulated checks pass. This is not actual approval or an onchain transaction.');document.getElementById('lab-description').textContent=names[val('type').value]+' · '+names[val('owner').value]+' · '+names[val('lease').value]+'. '+(val('lease').value==='rented'?L('Có hợp đồng thuê chưa đồng nghĩa đã thu được tiền.','An active lease does not prove rent has been received.'):L('Không có tiền thuê để phân phối khi chưa có nguồn thu thực.','No rent can be distributed without actual receipts.'))}
 document.querySelectorAll('#gp-onboarding select,#gp-onboarding input').forEach(e=>e.addEventListener('change',lab));lab();
}).catch(()=>{root.innerHTML='<section><h2>'+L('Chưa tải được dữ liệu Grand Park','Grand Park data could not be loaded')+'</h2><p>'+L('Vui lòng tải lại trang. Không hiển thị dữ liệu dự đoán thay thế.','Please reload the page. No inferred replacement data is displayed.')+'</p></section>'});
})();
